# R is the set {11k + 20m | k, m >= 0}
N_max = 200
R = set()
for k in range(N_max // 11 + 1):
    for m in range(N_max // 20 + 1):
        s = 11*k + 20*m
        R.add(s)

print(f"Size of R up to {N_max}: {len(R)}")
# Check closure property for a few elements in R
test_elements = [0, 11, 20, 31]
print("Checking closure:")
for n in test_elements:
    n_plus_11 = n + 11
    n_plus_20 = n + 20
    if n_plus_11 in R and n_plus_20 in R:
        print(f"n={n}: Closed (n+11={n_plus_11}, n+20={n_plus_20})")
    else:
        print(f"n={n}: NOT Closed (n+11={n_plus_11}, n+20={n_plus_20})")

